inner="\nfrom pathlib import Path\nimport json,numpy as np,torch\nfrom torch.nn import functional as F\nfrom experiments.pamf_phase1_flow import experiment as core,physical_rich_router_experiment as g,feature_conditioned_experiment as fs\nroot=Path('/home/szu2070436088/2510044040/CV-SincNet');torch.set_num_threads(2)\nmodels=g.load_models(root,'cpu');teacher,contract,dura,boundary,feature,_,_,_=models\ncache,clean,roles=core.data(root,contract)\nfrom leo_practical.channel import Config,receiver_for_session,stable_seed,normalize_input\nfrom leo_practical.residual import ResidualChannel\nids=np.load(cache/'train/physical_ids.npy',allow_pickle=False);rx=np.load(cache/'train/rx.npy',allow_pickle=False);day=np.load(cache/'train/day.npy',allow_pickle=False)\ngroups=[]\nfor role,count,initial,n in (('L_s',6300,128,1024),('U_s',56700,384,3072)):\n available=np.flatnonzero(roles==role);prior=available[np.linspace(0,count-1,initial,dtype=int)];available=np.setdiff1d(available,prior,assume_unique=True)\n for _ in range(3):\n  old=available[np.linspace(0,len(available)-1,n,dtype=int)];available=np.setdiff1d(available,old,assume_unique=True)\n take=128 if role=='L_s' else 384;prior=available[np.linspace(0,len(available)-1,take,dtype=int)];available=np.setdiff1d(available,prior,assume_unique=True)\n for _ in range(2):\n  old=available[np.linspace(0,len(available)-1,n,dtype=int)];available=np.setdiff1d(available,old,assume_unique=True)\n take=64 if role=='L_s' else 192;groups.append(available[np.linspace(0,len(available)-1,take,dtype=int)])\nix=np.concatenate(groups);assert len(ix)==len(np.unique(ix))==256\nix=np.concatenate((ix[:16],ix[64:112]));assert len(ix)==len(np.unique(ix))==64\n\nscenes=('practical_low_suburban','practical_mid_urban','practical_low_urban');factors=(.1,1.,10.,100.);namespace='phase1-source-convex-oracle-2026110211';views={};fits={}\nwith torch.no_grad():\n for view in ('clean',)+scenes:\n  if view=='clean':received=np.asarray(clean[ix],dtype=np.float32)\n  else:\n   cfg=Config(fs_hz=25e6,fc_hz=2462e6,scenario=view,processing_route='residual',mode='post_sync',equalization_enabled=False,reference_snr_db=30.,boundary='reflect')\n   received=[]\n   for j in ix:\n    pid=str(ids[j]);session='rx%d:day%d:eq1'%(int(rx[j]),int(day[j]));hw=receiver_for_session(cfg,2026110212,session)\n    value=np.asarray(clean[j],dtype=np.float64);signal,_=normalize_input(value[0]+1j*value[1]);result,meta=ResidualChannel(cfg,stable_seed(2026110211,namespace,view,pid),hw).process(signal)\n    assert np.isfinite(result).all() and not meta['channel_equalization_applied'];received.append(np.stack((result.real,result.imag)).astype(np.float32))\n   received=np.stack(received)\n  anchors=[]\n  for start in range(0,len(ix),32):anchors.append(dura(core.tensor(received[start:start+32],'cpu')).cpu())\n  anchors=np.from_dlpack(torch.cat(anchors).contiguous());candidates=[[] for _ in factors];fit_values=[]\n  for j in range(len(ix)):\n   # All quantities below are obtained from this received IQ and its frozen\n   # DURA restoration; no paired clean IQ, simulator parameters or labels.\n   y=received[j,0].astype(np.float64)+1j*received[j,1];prior=anchors[j,0].astype(np.float64)+1j*anchors[j,1]\n   n=len(y);m=9;idx=np.pad(np.arange(n),(m-1,0),mode='reflect');columns=idx[np.arange(n)[:,None]+m-1-np.arange(m)[None,:]]\n   X=prior[columns];gram=X.conj().T@X;ridge=.01*float(np.trace(gram).real)/m\n   h=np.linalg.solve(gram+max(ridge,1e-12)*np.eye(m),X.conj().T@y);residual=y-X@h\n   noise=max(float(np.mean(abs(residual)**2)),1e-12);prior_power=max(float(np.mean(abs(prior)**2)),1e-12)\n   fit_values.append(noise/prior_power);H=np.zeros((n,n),dtype=np.complex128)\n   np.add.at(H,(np.arange(n)[:,None],columns),np.broadcast_to(h,(n,m)))\n   eig,V=np.linalg.eigh(H.conj().T@H);rhs=V.conj().T@(H.conj().T@y);pv=V.conj().T@prior\n   for k,factor in enumerate(factors):\n    reg=factor*noise/prior_power;z=V@((rhs+reg*pv)/(np.maximum(eig,0)+reg))\n    assert np.isfinite(z).all();candidates[k].append(np.stack((z.real,z.imag)).astype(np.float32))\n  candidates=[np.stack(v) for v in candidates];fits[view]=dict(noise_ratio_median=float(np.median(fit_values)))\n  probabilities=[]\n  for start in range(0,len(ix),32):\n   inputs=[core.tensor(received[start:start+32],'cpu'),core.tensor(anchors[start:start+32],'cpu')]+[core.tensor(a[start:start+32],'cpu') for a in candidates]\n   probabilities.append(torch.stack([F.softmax(teacher.classify_features(teacher.features(z)),1) for z in inputs],1).cpu())\n  views[view]=np.from_dlpack(torch.cat(probabilities).contiguous());print('BLIND_PRIOR_SOURCE_PREDICTIONS_FIXED',view,flush=True)\nprint('ALL_SOURCE_PREDICTIONS_FIXED_BEFORE_SOURCE_LABELS',flush=True)\nlabels=fs.source_labels(root,cache,clean,roles,contract);labeled=roles[ix]=='L_s';assert np.all(labels[ix[~labeled]]==-1)\nref=views['clean'][:,0,:];teacher_target=ref.argmax(1);valid=labeled|(ref.max(1)>=.95);target=np.where(labeled,labels[ix],teacher_target);results=[]\nfor view in ('clean',)+scenes:\n pred=views[view].argmax(2);baseline=pred[:,1]==target\n row=dict(view=view,valid=int(valid.sum()),labeled=int((valid&labeled).sum()),pseudo=int((valid&~labeled).sum()),raw=int((valid&(pred[:,0]==target)).sum()),dura=int((valid&baseline).sum()),posterior=[])\n for j,factor in enumerate(factors):\n  right=pred[:,j+2]==target\n  row['posterior'].append(dict(residual_multiplier=factor,correct=int((valid&right).sum()),L_s_correct=int((valid&labeled&right).sum()),repairs=int((valid&~baseline&right).sum()),damages=int((valid&baseline&~right).sum())))\n results.append(row);print('BLIND_PRIOR_CHANNEL_SOURCE_RESULT',json.dumps(row),flush=True)\nprint('SOURCE_BLIND_PRIOR_CHANNEL '+json.dumps(dict(status='SOURCE_ONLY_BLIND_PRIOR_CHANNEL_DIAGNOSTIC',source_ids=len(ix),results=results,fits=fits,taps=9,channel_ridge_fraction=.01,\n labels='L_s actual; U_s high-confidence clean-teacher pseudo-targets',U_s_labels_read=0,V_reads=0,test_IQ_reads=0,predictions_before_source_labels=True,\n caveat='Per-record channel fitting uses only received IQ and frozen DURA output; this source diagnostic has no independent source-validation split, IDs overlap previous probes and fixed experts saw source records. Simulated data are not validated satellite data. Prior Phase1 test analysis motivated exploration.'),ensure_ascii=False),flush=True)\n"
